descriptor.templateCss:
* { box-sizing: border-box; }
.sf-widget {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    gap: 14px;
    font-family: 'Roboto', sans-serif;
    background: #ffffff;
}
.sf-fecha {
    padding: 6px 18px;
    border: 1px solid rgba(0, 0, 0, 0.12);
    border-radius: 4px;
    font-size: 14px;
    font-weight: 500;
    color: rgba(0, 0, 0, 0.87);
    letter-spacing: 0.2px;
}
.sf-flechas {
    display: flex;
    align-items: center;
    gap: 28px;
}
.sf-flecha {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: none;
    background: transparent;
    color: rgba(0, 0, 0, 0.6);
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
}
.sf-flecha:hover {
    background: rgba(0, 0, 0, 0.06);
}
.sf-flecha:active {
    background: rgba(0, 0, 0, 0.12);
}

descriptor.controllerScript:
// ============================================================
// Sustituto casero del widget nativo "date_range_navigator" de
// ThingsBoard -- ese nativo, con stepSize "day", SIEMPRE pinta el rango
// como "día - día siguiente" (p.ej. "29 - 30 Aug 2026"), sea cual sea la
// ventana de tiempo real -- es un comportamiento fijo del propio
// componente, no arreglable desde fuera. Este widget muestra un ÚNICO
// día y dos flechas para moverse día a día, controlando él mismo la
// ventana de tiempo del dashboard/diálogo.
//
// CAMBIO NUEVO: este widget es, en la práctica, el que SIEMPRE acierta el
// día que toca mostrar (se ha comprobado en logs reales). "cd.js" (la
// gráfica de días anteriores) se fiaba de su propio $ctx.timeWindow.minTime
// para saber que día pintar -- pero se ha comprobado que ese valor es una
// FOTO que cada widget se lleva al suscribirse, no una referencia
// compartida en vivo: hay una carrera de inicialización entre widgets del
// mismo estado en la que, a veces, "cd.js" se queda enganchado para
// siempre a la foto vieja (el día de antes de abrir el diálogo) aunque
// este widget ya haya corregido el día correctamente.
//
// Por eso, cada vez que este widget aplica un día (aplicarDia), ahora
// también lo publica en localStorage bajo 'riego_dia_actual' -- una
// clave que NO se borra nunca (a diferencia de la vieja
// 'riego_ts_ir_ayer', que sf.js consume y borra en su propio onInit).
// Cualquier otro widget del estado (cd.js) puede leer esa clave en
// cualquier momento para saber, con certeza, qué día hay que mostrar,
// sin depender de cuándo se suscribió cada uno.
// ============================================================
self.diaActual = null; // Date a las 00:00:00 del día que se está mostrando

var ultimoMinTimeVisto = null;

function inicioDia(d) {
    var r = new Date(d);
    r.setHours(0, 0, 0, 0);
    return r;
}
function finDia(d) {
    var r = new Date(d);
    r.setHours(23, 59, 59, 999);
    return r;
}
function formatearFecha(d) {
    return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}
// Publica el día actual para que otros widgets (cd.js) puedan leerlo sin
// depender de su propio $ctx.timeWindow -- ver nota de arriba.
function publicarDiaActual() {
    try {
        var paquete = { ts: self.diaActual.getTime(), publicadoEn: Date.now() };
        localStorage.setItem('riego_dia_actual', JSON.stringify(paquete));
    } catch (e) {
        console.error('[Selector de fecha] No se pudo publicar riego_dia_actual:', e);
    }
}
function pintar() {
    self.ctx.$container.find('.sf-fecha').text(formatearFecha(self.diaActual));
}
function aplicarDia(d, actualizarDashboard) {
    self.diaActual = inicioDia(d);
    publicarDiaActual();
    if (actualizarDashboard !== false) {
        self.ctx.dashboard.onUpdateTimewindow(self.diaActual.getTime(), finDia(self.diaActual).getTime());
    }
    pintar();
}


self.onInit = function() {
    console.log('[Selector de fecha] onInit() -- self.ctx.timeWindow=' + JSON.stringify(self.ctx.timeWindow));

    var diaInicial = null;
    var vieneDeIrAyer = false;

    try {
        var raw = localStorage.getItem('riego_ts_ir_ayer');
        if (raw) {
            localStorage.removeItem('riego_ts_ir_ayer');
            var datos = JSON.parse(raw);
            if (datos && typeof datos.ts === 'number' && (Date.now() - datos.creado) <= 10000) {
                diaInicial = new Date(datos.ts);
                vieneDeIrAyer = true;
            }
        }
    } catch (e) {
        console.error('[Selector de fecha] No se pudo leer riego_ts_ir_ayer:', e);
    }

    if (vieneDeIrAyer) {
        aplicarDia(diaInicial, true);
    } else if (self.ctx.timeWindow && self.ctx.timeWindow.minTime) {
        aplicarDia(new Date(self.ctx.timeWindow.minTime), false);
    } else {
        aplicarDia(new Date(), true);
    }

    ultimoMinTimeVisto = self.ctx.timeWindow ? self.ctx.timeWindow.minTime : null;
    console.log('[Selector de fecha] onInit() -- pintado inicial=' + self.diaActual + ' ultimoMinTimeVisto=' + ultimoMinTimeVisto);

    self.ctx.$container.find('.sf-prev').off('click').on('click', function() {
        var anterior = new Date(self.diaActual);
        anterior.setDate(anterior.getDate() - 1);
        aplicarDia(anterior, true);
    });
    self.ctx.$container.find('.sf-next').off('click').on('click', function() {
        var siguiente = new Date(self.diaActual);
        siguiente.setDate(siguiente.getDate() + 1);
        aplicarDia(siguiente, true);
    });
};

self.onDataUpdated = function() {
    var $ctx = self.ctx;
    if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) {
        console.log('[Selector de fecha] onDataUpdated() -- sin timeWindow.minTime todavia, se ignora.');
        return;
    }
    if (ultimoMinTimeVisto === $ctx.timeWindow.minTime) {
        console.log('[Selector de fecha] onDataUpdated() -- minTime sin cambios (' + $ctx.timeWindow.minTime + '), no se repinta.');
        return;
    }
    console.log('[Selector de fecha] onDataUpdated() -- minTime CAMBIA de ' + ultimoMinTimeVisto + ' a ' + $ctx.timeWindow.minTime + ' (' + new Date($ctx.timeWindow.minTime) + ') -- repintando.');
    ultimoMinTimeVisto = $ctx.timeWindow.minTime;
    aplicarDia(new Date($ctx.timeWindow.minTime), false);
};

self.onResize = function() {};
self.onDestroy = function() {};

